"""Temporal navigation candidate preserving the six structured contracts."""

# EVOLVE-BLOCK-START
MOTION_ACTIONS = ("FORWARD", "VEER_LEFT", "VEER_RIGHT")


def safety_contract(observation, memory):
    """Stop whenever confidence is low or collision risk is high."""
    if observation["safety_confidence"] < 0.60 or observation["closing_risk"] >= 0.75:
        memory["state"] = "STOPPED"
        return "STOP", 0.99
    return None


def tracking_contract(observation, memory):
    """Use short holds after loss, then perform a stable alternating scan."""
    reliable = (
        bool(observation["target_visible"])
        and observation["target_confidence"] >= 0.55
        and observation["target_identity_confidence"] >= 0.60
    )
    if reliable:
        memory["search_age"] = 0
        if observation["track_age"] < 2:
            memory["state"] = "VERIFY"
            return "SLOW_DOWN", 0.80
        return None

    lost = int(observation["lost_steps"])
    if memory.get("state") in {"LOCKED", "APPROACH", "REACQUIRE"} and lost <= 2:
        memory["state"] = "REACQUIRE"
        return "STOP", 0.92

    age = int(memory.get("search_age", 0)) + 1
    memory["search_age"] = age
    direction = memory.get("scan_direction", "SCAN_LEFT")
    if age % 2 == 1:
        direction = "SCAN_RIGHT" if direction == "SCAN_LEFT" else "SCAN_LEFT"
        memory["scan_direction"] = direction
    memory["state"] = "SEARCH"
    return direction, 0.75


def propose_moves(observation, memory):
    """Build unique corridor-admissible motions ordered by bearing."""
    bearing = float(observation["target_bearing"])
    moves = []
    if abs(bearing) <= 10.0 and observation["corridor_center"]:
        moves.append("FORWARD")
    if bearing < 0.0 and observation["corridor_left"]:
        moves.append("VEER_LEFT")
    if bearing > 0.0 and observation["corridor_right"]:
        moves.append("VEER_RIGHT")
    if observation["corridor_center"]:
        moves.append("FORWARD")
    if observation["corridor_left"]:
        moves.append("VEER_LEFT")
    if observation["corridor_right"]:
        moves.append("VEER_RIGHT")
    return list(dict.fromkeys(moves))


def progress_contract(observation, memory, candidates):
    """Choose the motion minimizing bearing error with turn hysteresis."""
    if not candidates:
        return None
    bearing = float(observation["target_bearing"])
    previous = memory.get("last_action")
    preferred = "FORWARD" if abs(bearing) <= 10.0 else (
        "VEER_LEFT" if bearing < 0.0 else "VEER_RIGHT"
    )
    if preferred in candidates:
        action = preferred
    else:
        action = candidates[0]
    if previous in {"VEER_LEFT", "VEER_RIGHT"} and abs(bearing) < 7.0:
        if "FORWARD" in candidates:
            action = "FORWARD"
    memory["last_action"] = action
    return action


def termination_contract(observation, memory):
    """Return a safe stationary fallback when no motion is admissible."""
    memory["state"] = "STOPPED"
    return "STOP", 0.98


def decide(observation, memory):
    """Compose safety, tracking, progress, and termination into three outputs."""
    memory = dict(memory or {})
    safety = safety_contract(observation, memory)
    if safety is not None:
        return safety[0], safety[1], memory

    tracking = tracking_contract(observation, memory)
    if tracking is not None:
        return tracking[0], tracking[1], memory

    memory["state"] = "LOCKED"
    if observation["target_distance_class"] == "near":
        aligned = (
            abs(float(observation["heading_error"])) <= 15.0
            and observation["target_identity_confidence"] >= 0.80
        )
        if aligned:
            memory["state"] = "ARRIVED"
            return "ARRIVED", 0.96, memory
        error = float(observation["target_bearing"])
        if abs(error) < 1.0:
            error = float(observation["heading_error"])
        candidates = [
            "VEER_LEFT" if error < 0.0 else "VEER_RIGHT"
        ]
    else:
        candidates = propose_moves(observation, memory)

    action = progress_contract(observation, memory, candidates)
    if action is None:
        fallback = termination_contract(observation, memory)
        return fallback[0], fallback[1], memory

    memory["state"] = "APPROACH"
    return action, 0.90, memory


# EVOLVE-BLOCK-END
